import {Link, Flash} from '@primer/react'
import {Dialog} from '@primer/react/experimental'
import {deleteBranch} from './BranchActionMenu'
import type {PullRequest} from '../types'
import type {Repository} from '@github-ui/current-repository'
import {useState} from 'react'
import {usePullRequestConfig} from '../contexts/PullRequestConfigContext'

import styles from './DeleteBranchDialog.module.css'

export interface DeleteBranchDialogProps {
  showModal: boolean
  setShowModal: (showModal: boolean) => void
  setDeleting: (isDeleting: boolean) => void
  branchName: string
  onDelete: (branchName: string) => void
  pullRequest?: PullRequest
  repo: Repository
}

export function DeleteBranchDialog({
  showModal,
  setShowModal,
  setDeleting,
  branchName,
  onDelete,
  pullRequest,
  repo,
}: DeleteBranchDialogProps) {
  const {enabled: pullRequestsEnabled} = usePullRequestConfig()
  const [showErrorBanner, setShowErrorBanner] = useState(false)

  return (
    <>
      {showModal && (
        <Dialog
          title="Delete branch"
          width="large"
          onClose={() => {
            setShowModal(false)
          }}
          footerButtons={[
            {
              content: 'Cancel',
              buttonType: 'normal',
              onClick: () => {
                setShowModal(false)
              },
            },
            {
              content: 'Delete',
              buttonType: 'danger',
              onClick: async () => {
                const ok = await deleteBranch(setDeleting, branchName, onDelete, repo)
                if (!ok) {
                  setShowErrorBanner(true)
                } else {
                  setShowErrorBanner(false)
                  setShowModal(false)
                }
              },
            },
          ]}
        >
          <div className="js-delete-dialog-body">
            {showErrorBanner && (
              <Flash variant="danger" aria-live="assertive" role="alert" className={styles.WarningFlash}>
                Branch could not be deleted
              </Flash>
            )}
            {pullRequestsEnabled && pullRequest ? (
              <>
                <p>
                  The branch <span className={styles.BranchName}>{branchName}</span> is associated with an open pull
                  request:
                </p>
                <ul className={styles.PullRequestList}>
                  <li>
                    <Link href={pullRequest.permalink}>
                      #{pullRequest.number} - {pullRequest.title}
                    </Link>
                  </li>
                </ul>
                <p className={styles.WarningText}>If you delete this branch, the pull request will be closed.</p>
              </>
            ) : (
              <p>
                The branch <span className={styles.BranchName}>{branchName}</span> will be permanently deleted.
              </p>
            )}
            <p>Are you sure you want to delete this branch?</p>
          </div>
        </Dialog>
      )}
    </>
  )
}

export default DeleteBranchDialog
